(569281, 58364, 9906, '<td valign="top">This would be awesome if it had one distinct shadow rather than the multiple ones here...<br/>tTC</td>', 'This would be awesome if it had one distinct shadow rather than the multiple ones here...tTC', '2004-02-04 23:23:06.000000', NULL, 1),
