(571811, 58365, 17024, '<td valign="top">I like the use of a textured background.</td>', 'I like the use of a textured background.', '2004-02-07 11:21:51.000000', NULL, 1),
(571816, 58367, 17024, '<td valign="top">Neat picture. Very cool.</td>', 'Neat picture. Very cool.', '2004-02-07 11:30:55.000000', NULL, 1),
