(572854, 58276, 200, '<td valign="top">wonderful</td>', 'wonderful', '2004-02-09 00:16:40.000000', NULL, 0),
(572857, 58251, 16703, '<td valign="top">i cant believe this ended up being in the 19th place... such a shame... but i congradulate you anyway because of your awesome photograph...</td>', 'i cant believe this ended up being in the 19th place... such a shame... but i congradulate you anyway because of your awesome photograph...', '2004-02-09 00:20:20.000000', NULL, 0),
(572858, 58358, 8159, '<td valign="top">This was my favorite pic in this challenge. Terrific idea and very well executed. Congrats on the win!</td>', 'This was my favorite pic in this challenge. Terrific idea and very well executed. Congrats on the win!', '2004-02-09 00:21:22.000000', NULL, 0),
(572865, 58358, 11078, '<td valign="top">I said you would win in my pre challenge comment! <br/>So Congratulations well deserved!<br/>How someone can give you a 1 for that I''ll never know <br/>I gave it a 10 and Thats how it should be Well done<br/><br/><i>Message edited by author 2004-02-09 00:27:35.</i></td>', 'I said you would win in my pre challenge comment! So Congratulations well deserved!How someone can give you a 1 for that I''ll never know I gave it a 10 and Thats how it should be Well done', '2004-02-09 00:25:48.000000', '2004-02-09 00:27:35.000000', 0),
